            <div class="candidate-picture-name-position">

              <div class="candidate-picture-name-nc-position-inner-box">
                <img src="/web/20161015162943im_/http://2016election.procon.org/images/election/80x80bw/john-kasich-small.jpg" alt="John Kasich" title="John Kasich"/>
