                };
                /* Add the current barrier status to the CM call */
                TNY.addBarrierState = function() {
                    // Retire this line Sept 1 2015
                    deviceParams = deviceParams + "&amp;article_count=" + TNY.meterVar.barrier_status;

                    deviceParams = deviceParams + "&amp;barrier_state=" + TNY.meterVar.barrier_status;
                };
                TNY.addSubscriberState = function() {
                    // Subscriber state
                    deviceParams = deviceParams + "&amp;subscriber_state=" + TNY.meterVar.subscription;

                    // Subscriber details
                    if ( typeof TNY.meterVar.entitlement !== '' && typeof TNY.meterVar.entitlement.subscriberStatus !== 'undefined' ) {
                        deviceParams = deviceParams + "&amp;subscriber_details=" + TNY.meterVar.entitlement.subscriberStatus;
                    }

                    // Meter max
                    deviceParams = deviceParams + "&amp;meter_max=" + TNY.meterVar.meter_max;

                    // Meter count
                    deviceParams = deviceParams + "&amp;meter_count=" + TNY.meterVar.meter_count;

                    // Meter name
                    deviceParams = deviceParams + "&amp;meter_name=" + TNY.meterVar.meter_name;

                    // Meter AB Test values
                    deviceParams = deviceParams + "&amp;meter_ab_group=" + TNY.meterVar.meter_ab_group;
                    deviceParams = deviceParams + "&amp;meter_ab_value=" + TNY.meterVar.meter_ab_value;

                    if ( typeof localStorage !== undefined ) {
                        // Per-Meter Counting
                        var current_meter = TNY.meterVar.meter_name;

                        // Visits count
                        var visitedCount = localStorage.getItem( "visitedCount_"+current_meter ) || 0;
                        deviceParams = deviceParams + "&amp;visit_count=" + visitedCount;

                        // Barrier Views
                        if ( TNY.meterVar.meter_count <= TNY.meterVar.meter_max && EVOLOK.exceededMeter !== '1' ) {
                            barrier_views = 0;
                        } else {
                            barrier_views = ( visitedCount - TNY.meterVar.meter_max );
                        }
                        deviceParams = deviceParams + "&amp;barrier_views=" + barrier_views;
                    }
                };
                if ( TNY.meterVar.barrier_status == "half" || TNY.meterVar.barrier_status == "full" ) {
                    TNY.checkIfBarrierIsShown();
                    TNY.addBarrierState();
                    TNY.addSubscriberState();
