			<a class="addthis_button_tweet" style="float:left; width:90px;"></a> 

			<a class="addthis_button_google_plusone" style="width:90px; float:left;"></a>
           <!-- <a class="addthis_button_pinterest_share" style="display:inline-block; margin-bottom:5px; padding-left:30px; width:100%;"></a>
            <a class="addthis_button_reddit" style="display:inline-block; margin-bottom:5px; padding-left:30px; width:100%;"></a>
