(adsbygoogle = window.adsbygoogle || []).push({});
</script></div>
&nbsp;
&nbsp;
&nbsp;
<br>
<div style="font-size: 10; display: block; margin-bottom: 0px; margin-top: 10px;"><p style="text-align: center;"> Click below to continue through the article.</p></div></div></div></p>
								<!-- Start Modified Pagination -->
								<div class="pagination">
