ound-position: left top;} @media only screen and (max-width: 800px) { .related-background-img {margin:20px auto; float:none;} .related-quotes-img {margin:20px auto; float:none;} .related-video-img {margin: 20px auto; float:none;} .related-background-img:hover {margin:20px auto; float:none;} .related-quotes-img:hover {margin:20px auto; float:none;} .related-video-img:hover {margin: 20px auto; float:none;} }
