ntdown_clock":true,"dynamic_header":false,"dynamic_header_name":false,"subscribe_link_mobile":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/subscription.time.com\/storefront\/subscribe-to-time\/link\/1019575.html","subscribe_link_desktop":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/subscription.time.com\/storefront\/subscribe-to-time\/link\/1019480.html","dividers":["<section class=\"read-more-divider-grid\">\n\t<div class=\"divider-300x600\" data-cb-ad-id=\"divider-300x600\"><\/div>\n\t<div class=\"articles\">\n\t\t<article class=\"related-article\">\n\t\t\t<a class=\"article-thumbnail-wrap\" href=\"http:\/\/time.com\/3724505\/healthy-recipes-healthiest-foods\/\" data-event=\"article-divider\"><img class=\"article-thumbnail\" src=\"https:\/\/timedotcom.files.wordpress.com\/2015\/02\/50-healthiest-foods-2015.gif?w=100&amp;h=100&amp;crop=1\" alt=\"{short_title}}\"><\/a>\n\t\t\t\n\t\t\t<section class=\"tags\">\n\t\t\t\t<a class=\"section-tag\" href=\"http:\/\/time.com\/health\/\" data-event=\"article-divider\">Health<\/a>\n\t\t\t<\/section>\n\t\t\t<a class=\"article-title-link\" href=\"http:\/\/time.com\/3724505\/healthy-recipes-healthiest-foods\/\"  data-event=\"article-divider\"><h4 class=\"article-title\">The 50 Healthiest Foods of All Time<\/h4><\/a>\n\t\t\t\n\t\t<\/article>\n\t\t<article class=\"related-article\">\n\t\t\t<a class=\"article-thumbnail-wrap\" href=\"http:\/\/time.com\/3998401\/summer-music-playlist-songs\/\" data-event=\"article-divider\"><img class=\"article-thumbnail\" src=\"https:\/\/timedotcom.files.wordpress.com\/2015\/08\/santigold.jpg?quality=85&amp;w=100&amp;h=100&amp;crop=1\" alt=\"{short_title}}\"><\/a>\n\t\t\t\n\t\t\t<section class=\"tags\">\n\t\t\t\t<a class=\"section-tag\" href=\"http:\/\/time.com\/entertainment\/\" data-event=\"article-divider\">Entertainment<\/a>\n\t\t\t<\/section>\n\t\t\t<a class=\"article-title-link\" href=\"http:\/\/time.com\/3998401\/summer-music-playlist-songs\/\"  data-event=\"article-divider\"><h4 class=\"article-title\">15 Great Songs You Might Have Missed This Summer<\/h4><\/a>\n\t\t\t\n\t\t<\/article>\n\t\t<article class=\"related-article\">\n\t\t\t<a class=\"article-thumbnail-wrap\" href=\"http:\/\/time.com\/3994716\/world-travel-movies\/\" data-event=\"article-divider\"><img class=\"article-thumbnail\" src=\"https:\/\/timedotcom.files.wordpress.com\/2015\/08\/under-the-tuscan-sun.jpg?quality=85&amp;w=100&amp;h=100&amp;crop=1\" alt=\"{short_title}}\"><\/a>\n\t\t\t\n\t\t\t<section class=\"tags\">\n\t\t\t\t<a class=\"section-tag\" href=\"http:\/\/time.com\/entertainment\/\" data-event=\"article-divider\">Entertainment<\/a>\n\t\t\t<\/section>\n\t\t\t<a class=\"article-title-link\" href=\"http:\/\/time.com\/3994716\/world-travel-movies\/\"  data-event=\"article-divider\"><h4 class=\"article-title\">30 Movies That Will Inspire You to Travel the World<\/h4><\/a>\n\t\t\t\n\t\t<\/article>\n\t<\/div>\n<\/section>"],"single_article":{"url":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/time.com\/4100408\/a-criminologists-case-against-gun-control\/","shortlink":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/ti.me\/1KY0I4s","title":"A Criminologist&#8217;s Case Against Gun Control","friendly_title":"A Criminologist\u2019s Case Against Gun Control","post_type":"post","available":true,"time_article":true,"comments_allowed":true,"sub_learn_more_url":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/subscription.time.com\/storefront\/subscribe-to-time\/link\/1032487.html","show_comments":true,"short_title":"A Criminologist&#8217;s Case Against Gun Control","contributor":true,"excerpt":"A law professor explains why he is skeptical about new approaches to gun violence in America","format":"brief","time":{"pretty":"Dec. 1, 2015","published":"2015-12-01 13:09:09","updated":"2015-12-01 18:09:09","minute":"1:09 pm","short":"12\/1"},"authors":[{"id":238588283,"url":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/time.com\/author\/jacob-davidson\/","name":"Jacob Davidson","bio":"Jacob Davidson is a news editor at Time. He previously worked at Money as a reporter\/producer, covering tech, the economy, and everyday finance.","short_bio":"Jacob Davidson is a news editor at Time.","types":["time staff"],"twitter":"JakeD","twitter_url":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/twitter.com\/JakeD","gplus":"","fb":"","email":"jake.davidson@yoh.timeinc.com","thumbnail":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/i0.wp.com\/timedotcom.files.wordpress.com\/2015\/12\/jake-davidson-2.jpg?crop=35px%2C18px%2C872px%2C872px&resize=100%2C100&quality=85&strip&ssl=1","contributor":true,"search_link":false}],"has_authors":true,"content":"<aside class=\"right-rail__container right-rail__container--ad\"><div class=\"right-rail__ad__wrapper right-rail__module\"><div class=\"right-rail__ad\" id=\"right-rail__ad-4100408\"><\/div><\/div><br \/>\n<div class=\"OUTBRAIN right-rail__outbrain right-rail__module\" data-src=\"http:\/\/time.com\/4100408\/a-criminologists-case-against-gun-control\/\" data-widget-id=\"SB_2\" data-ob-template=\"timemag\"><\/div><\/aside>\n<p class=\"p1\">In the wake of the recent mass shooting at a Colorado Planned Parenthood that claimed three lives, President Barack Obama called the incidents of gun violence in America &#8220;not normal.&#8221; &#8220;Enough is enough,&#8221; Obama said. <a href=\"http:\/\/shootingtracker.com\/wiki\/Mass_Shootings_in_2015\" target=\"_blank\"><span class=\"s1\">According to one count<\/span><\/a>, there have been 351 mass shootings in the United States in 2015. The frequency of these shootings has led many to call for new approaches to guns and violence in America. In a <a href=\"http:\/\/www.quinnipiac.edu\/news-and-events\/quinnipiac-university-poll\/national\/release-detail?ReleaseID=2300\" target=\"_blank\"><span class=\"s1\">Nov. 5 national survey<\/span><\/a>, for instance, 52 percent of respondents said they support &#8220;stricter gun laws.&#8221; (The number who said they supported &#8220;gun control&#8221; was smaller.)<\/p>\n<div class=\"article-video ad_brightcove_video right-rail-adjacent\"><div id=\"ad_brightcove\" class=\"ad_brightcove_video-wrapper\"><\/div><\/div>\n<p class=\"p1\"><span class=\"s2\">In an interview, James Jacobs, <\/span>director of Center for Research in Crime and Justice at New York University School of Law, a professor of constitutional law, and the author of <a href=\"http:\/\/getit.library.nyu.edu\/go\/9383879\" target=\"_blank\"><span class=\"s3\"><i>Can Gun Control Work?<\/i><\/span><\/a><i>, <\/i>discusses what he sees as the challenges facing those who would like to change the country&#8217;s approach to gun violence and gun laws.<\/p>\n<p><strong>What&rsquo;s the most common misunderstanding about gun control?<\/strong><\/p>\n<p>There are so many misunderstandings that it&rsquo;s hard to know where to begin. For one, we need to remember that we&#8217;ve have had a <a href=\"http:\/\/www.pewsocialtrends.org\/2013\/05\/07\/gun-homicide-rate-down-49-since-1993-peak-public-unaware\/\" target=\"_blank\">remarkable decrease<\/a> in violent crime and gun crime in the U.S. since the early 1990s, even though the number of firearms <a href=\"http:\/\/engagedscholarship.csuohio.edu\/cgi\/viewcontent.cgi?article=1679&amp;context=urban_facpub\" target=\"_blank\">has increased by about 10 million every year<\/a>. There&rsquo;s no simple correspondence between the number of firearms in private hands and the amount of gun crime, and I often find it somewhat strange that there seems to be a perception that things are worse than ever when, in reality, things are really better than they&rsquo;ve been for decades.<\/p>\n<p><strong>Read More: <\/strong><a href=\"http:\/\/time.com\/4108421\/brazil-u-s-gun-culture\/\">Brazil Seeks to Copy U.S. Gun Culture<\/a><\/p>\n<p>People should also be aware that <a href=\"http:\/\/www.cdc.gov\/nchs\/data\/nvsr\/nvsr64\/nvsr64_02.pdf\" target=\"_blank\">most gun-related deaths are suicides, not murders<\/a>. There are twice as many suicides in the U.S. by guns as there are homicides and I think most people find that very surprising. Over and over again one reads that 30,000 people have been killed with guns, but what&rsquo;s not said is that 20,000 of them took their own lives.<\/p>\n<p>But perhaps the most common misperception of all, and the point I want to underline time and again is that there is no simple, effective policy to reduce gun crime that is just there for the asking as long as we have the political will to do it. That solution doesn&rsquo;t exist. It&rsquo;s very hard to find an initiative that is implementable and enforceable that would make any kind of an impact on gun crime.<\/p>\n<p><strong>Would an assault weapon ban help prevent mass shootings?<\/strong><\/p>\n<p class=\"p1\">Many people want to ban so-called assault weapons because they believe these firearms are uniquely dangerous, or the same as machine guns. They are not. Assault weapons&mdash;at least the ones available to civilians&mdash;are like all semi-automatics and fire one bullet with one pull of the trigger. What makes an assault weapon different than a regular rifle are the <a href=\"http:\/\/www.nytimes.com\/2013\/01\/17\/us\/even-defining-assault-weapons-is-complicated.html?pagewanted=1\" target=\"_blank\">cosmetic &#8220;military-like&#8221; features<\/a>, such as a bayonet mount or pistol grip and so forth, none of which have functional significance. Assault weapons are not more powerful, they do not shoot more bullets, and they do not shoot faster. We would not be a safer society if we could eliminate all of the assault weapons because people could substitute for them non-assault weapons that are exactly the same.<\/p>\n<p><strong>President Obama has held up Australia and England as examples of gun control reducing gun violence. Would their policies work in the U.S.?<\/strong><\/p>\n<p class=\"p1\"><span class=\"s1\">The U.K. has gone the farthest in <a href=\"https:\/\/www.gov.uk\/government\/uploads\/system\/uploads\/attachment_data\/file\/417199\/Guidance_on_Firearms_Licensing_Law_v13.pdf\" target=\"_blank\">restricting the private ownership of guns<\/a><\/span>. Shotguns and rifles are only permitted to those who can pass through an arduous police-administered licensing process, and after the 1996 massacre in Dunblane, Scotland, <a href=\"http:\/\/www.cnn.com\/2012\/12\/17\/world\/europe\/dunblane-lessons\/\" target=\"_blank\">ownership of handguns was prohibited<\/a>. But the U.K.&#8217;s policy could not work in the U.S. because we have a Constitution, we have a Second Amendment, and we have a Supreme Court decision that guarantees the right of Americans to keep and bear arms in their home for lawful purposes. So we cannot have a prohibition of private ownership of firearms.<\/p>\n<p class=\"p1\">Australia had a <a href=\"http:\/\/nymag.com\/daily\/intelligencer\/2015\/10\/how-australia-and-britain-tackled-gun-violence.html\" target=\"_blank\">gun buyback program<\/a> and prohibited new purchases of many types of firearms. We have tried gun buybacks in the United States and they have been <a href=\"https:\/\/www.bostonglobe.com\/metro\/2014\/02\/12\/success-gun-buyback-program-debated\/PsITjPCyPkrG9C7fFr979O\/story.html\" target=\"_blank\">unsuccessful<\/a>. People do not wish to sell their guns to the government, and those who do almost invariably sell old guns so they can get the money and buy new guns.<\/p>\n<p><strong>Another popular proposed policy is mandating background checks for private sales. Would that be an effective way to reduce gun crime?<\/strong><\/p>\n<p>I think that requiring background checks for all gun sales, period, would be a good idea in principle. The problem is implementing and enforcing such a system. There&rsquo;s no universal registry of firearms, so if the police were to arrest somebody and try to prosecute whoever sold them their gun without the required check, there&#8217;s no way to verify who the seller was or when the sale took place. To have an effective system of regulating private sales you would need a registry, and the idea of a registry is an anathema to the gun owning community because they see a registration system as a precursor to a general confiscation&mdash;which it was in the U.K. and has been in other countries as well.<\/p>\n<p>But even if we could politically will a gun registry into existence, it&#8217;s unlikely that it would work. In the few states where we have a requirement that assault weapons be registered, no more than 10% of the owners of assault weapons <a href=\"http:\/\/www.usatoday.com\/story\/news\/nation\/2015\/06\/23\/gun-group-cites-low-compliance\/29193905\/\" target=\"_blank\">have generally gone through<\/a> the <a href=\"http:\/\/www.nytimes.com\/1990\/12\/24\/us\/california-gun-control-law-runs-into-rebellion.html?pagewanted=all\" target=\"_blank\">registration process<\/a>, meaning at least 90% of the people don&rsquo;t register. Other countries have also had a difficult time making registration work. The <span class=\"s1\">Canadians <\/span>have registered handguns since the 1930s. In 1993, the liberal government initiated shotgun and long gun <span class=\"s1\">registration<\/span>. The program attracted a great deal of criticism, huge cost overruns and resistance from firearms owners, and in 2012 the Conservative government<a href=\"http:\/\/www.cbc.ca\/news\/multimedia\/the-rise-and-fall-of-canada-s-long-gun-registry-1.2862001\" target=\"_blank\"> scrapped the program and destroyed the registry.<\/a> That might give people pause for thought about the feasibility of a registration program.<\/p>\n<p>Another problem with background checks is surveys of inmates show overwhelmingly that criminals obtain guns on the <a href=\"http:\/\/bjs.gov\/content\/pub\/pdf\/fuo.pdf\" target=\"_blank\">black market or the grey market<\/a>. Almost no prison inmates say they went to a licensed dealer and filled out forms. And why would they? Even the <a href=\"http:\/\/www.pewresearch.org\/fact-tank\/2013\/06\/04\/a-minority-of-americans-own-guns-but-just-how-many-is-unclear\/\" target=\"_blank\">lowest estimates<\/a> show 30% of U.S. households own at least one firearm, making it very easy for someone banned from purchasing a gun to obtain one from a friend, family member, or fellow criminal who already has one.<\/p>\n<p><strong>Politicians on both sides of the gun control debate have supported doing more to keep guns away from the mentally ill. Would that work?<\/strong><\/p>\n<p>It seems sensible to practically everybody that people who are extremely mentally ill are not reliable enough to be gun owners, but building a policy around that is more complicated than one might think. The federal law says that a person who has ever been <a href=\"http:\/\/www.ncsl.org\/research\/civil-and-criminal-justice\/possession-of-a-firearm-by-the-mentally-ill.aspx\" target=\"_blank\">involuntarily committed<\/a> to a mental hospital or who has been found by a court to be mentally defective is prevented from buying a firearm, but that would disqualify a very small number of people.<\/p>\n<p>If we wanted to move beyond this, we&#8217;d have to expand the definition of who is mentally ill&mdash;no easy task&mdash;and even if we did, the government has had a difficult time getting mental illness data on individuals because many in the mental health treatment community <a href=\"http:\/\/thinkprogress.org\/health\/2013\/01\/16\/1455721\/mental-health-ny-gun-safety\/\" target=\"_blank\">strongly oppose these types of controls<\/a>. They believe mental disqualifications are stigmatizing, that they would deter people from seeking treatment, and that they are detrimental to the therapeutic relationship. As a result, there&rsquo;s been strong opposition from these groups when more aggressive laws on guns and mental illness are proposed.<\/p>\n<p><strong>In your view what&rsquo;s the most effective thing the U.S. can do to reduce gun violence?<\/strong><\/p>\n<p>I think we need to work on law enforcement strategies aiming at the people who are most likely to commit gun crimes, so we&rsquo;re looking at drug dealers, gang members, people who have engaged in violent crime in the past, and the areas in which they operate. We should also draw a line in the sand&mdash;a serious red line&mdash;that if you commit a gun crime, you&rsquo;re going to do a lot of prison time. That policy is uncontroversial and we can work off that consensus.<\/p>\n<p>Of course, even that approach won&#8217;t catch everybody&mdash;there is just no overall panacea to the problem of gun violence&mdash;but I think we should be talking in terms of crime control rather than trying keep irresponsible and dangerous people from getting a weapon in the first place.<\/p>\n","read_more":true,"section":{"name":"Ideas","slug":"ideas","url":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/time.com\/ideas\/","description":"TIME Ideas hosts the world's leading voices, providing commentary on events in news, society, and culture. We welcome outside contributions. Opinions expressed do not necessarily reflect the views of TIME editors.","ideas":true},"tag":{"name":"Crime","slug":"crime","url":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/time.com\/tag\/crime\/"},"tags":"Crime","id":4100408,"encoded_url":"http%3A%2F%2Ftime.com%2F4100408%2Fa-criminologists-case-against-gun-control%2F","encoded_shortlink":"http%3A%2F%2Fti.me%2F1KY0I4s","encoded_title":"A+Criminologist%E2%80%99s+Case+Against+Gun+Control","twitter_text":"A%20criminologist%27s%20case%20against%20gun%20control","social_encoded_url":{"facebook":"http%3A%2F%2Ftime.com%2F4100408%2Fa-criminologists-case-against-gun-control%2F%3Fxid%3Dfbshare","twitter":"http%3A%2F%2Fti.me%2F1IAZXi9","linkedin":"http%3A%2F%2Ftime.com%2F4100408%2Fa-criminologists-case-against-gun-control%2F%3Fxid%3Dlinkedinshare","google":"http%3A%2F%2Ftime.com%2F4100408%2Fa-criminologists-case-against-gun-control%2F%3Fxid%3Dgplusshare","whatsapp":"A%20criminologist%27s%20case%20against%20gun%20control%0Ahttp%3A%2F%2Ftime.com%2F4100408%2Fa-criminologists-case-against-gun-control%2F%3Fxid%3Dwhatsappshare","pinterest":"http%3A%2F%2Ftime.com%2F4100408%2Fa-criminologists-case-against-gun-control%2F%3Fxid%3Dpinterestshare","pinterest_image":"https%3A%2F%2Ftimedotcom.files.wordpress.com%2F2015%2F12%2Fgun.jpg%3Fquality%3D85%26w%3D550"},"ads":{"neg":"false","post_title":"A Criminologist's Case Against Gun Control"},"email_title":"A%20Criminologist%E2%80%99s%20Case%20Against%20Gun%20Control%20%7C%20TIME","email_body":"A%20Criminologist%E2%80%99s%20Case%20Against%20Gun%20Control%0A%0AA%20law%20professor%20explains%20why%20he%20is%20skeptical%20about%20new%20approaches%20to%20gun%20violence%20in%20America%0A%0Ahttp%3A%2F%2Ftime.com%2F4100408%2Fa-criminologists-case-against-gun-control%2F%3Fxid%3Demailshare","omniture":{"modules":"[time-rail-ad]|[outbrain-video-module]"},"outbrain":{"url":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/time.com\/4100408\/a-criminologists-case-against-gun-control\/","desktop_widget_id":"AR_6","mobile_widget_id":"MB_1","2x2":"AR_9","widget_id":"AR_6","rr_widget_id_1":"SB_2","rr_widget_id_2":"SB_4"},"classes":"metered","article_tile_thumbnail":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/timedotcom.files.wordpress.com\/2015\/12\/gun.jpg?quality=85&w=74&h=74&crop=1","trending_video_image":{"class":"article_trending_medium","thumbnail":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/timedotcom.files.wordpress.com\/2015\/12\/gun.jpg?quality=85&w=100&h=100&crop=1","src":{"landscape_large":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/timedotcom.files.wordpress.com\/2015\/12\/gun.jpg?quality=85&w=550&h=367&crop=1","large":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/timedotcom.files.wordpress.com\/2015\/12\/gun.jpg?quality=85&w=405&h=229&crop=1","square":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/timedotcom.files.wordpress.com\/2015\/12\/gun.jpg?quality=85&w=600&h=600&crop=1"},"credit":"Getty Images","caption":"","title":"","alt":"","providers":[],"masonry":{"small_width":300,"small_height":225,"large_width":625,"large_height":469}},"titles_outbrain":{"url":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/time.com\/4100408\/a-criminologists-case-against-gun-control\/","desktop_widget_id":"AR_8","mobile_widget_id":"MB_2","widget_id":"AR_8"},"seo":{"title":"A Criminologist's Case Against Gun Control","description":"A criminologist and gun control skeptic explains why it won't work","google_news":"gun control, gun policy, nra, james jacobs, firearms restrictions, gun crime, crime, nyu","keywords":"crime","og_title":"A Criminologist's Case Against Gun Control","og_desc":"A criminologist and gun control skeptic explains why it won't work","canonical_link":""},"amp_link":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/amp.timeinc.net\/time\/4100408\/a-criminologists-case-against-gun-control\/?source=dam","next_article":{"url":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/time.com\/4544336\/halloween-movies-babadook\/","shortlink":"http:\/\/web.archive.org\/web\/20161027021018\/http:\/\/ti.me\/2eNmCzL","title":"11 Spooky Movies to Stream This Halloween","friendly_title":"11 Spooky Movies to Stream This Halloween","post_type":"post","available":true,"time_article":true,"sub_learn_more_url":"http:\/\/web.archive.org\/web\/20161027021018\/https:\/\/subscription.time.com\/storefront\/subscribe-to-time\/link\/1032487.html","short_title":"11 Spooky Movies to Stream This Halloween","excerpt":"It's the most frightening time of the year","format":"list","time":{"pretty":"5:41 PM ET","published":"2016-10-26 17:41:50","updated":"2016-10-26 21:41:50","minute":"5:41 pm","short":"5:41 PM ET"},"authors":[{"id":430938187,"url":"http:\/\/web.archiv