		  			</div></div><script>var w=0;var aw=0;var sls=$(".large a");sls.click(function(){ if(w=="170%"){w="100%";aw=0;$("#ppt").css("float","right");} else {w="170%";aw="-70%";$("#ppt").css("float","left");} sls.parent().parent().parent().css("width",w);sls.parent().parent().css("width",w);sls.parent().parent().next().css("width",w);$("#ppt > a.next").css("right",aw); });</script>
