<style>
.wh_transf {
    position: fixed;
    top: 0px;
    left: 0px;
    width: 100%;
    height: 100%;
    background: none repeat scroll 0% 0% rgba(235, 235, 235, 0.8);
    z-index: 99999;
    margin-top: 0px;
}

.option {
    font-size: 13px;
    vertical-align: top;
    color: #fff;
    padding-top: 7px;

}

.close {
    width: 33px;
    height: 33px;
    position: absolute;
    top: -10px;
    right: -10px;
}

.rword {
	margin-top: 5px;
	color: #fff;
	font-size: 13px;
}
::-webkit-input-placeholder {
   color: #999;
}

:-moz-placeholder { /* Firefox 18- */
   color: #999;
}

::-moz-placeholder {  /* Firefox 19+ */
   color: #999;
}

:-ms-input-placeholder {
   color: #999;
}
</style>

